package com.Neha1.programs;

public class SwitchVowel {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		String ch="a";
		switch(ch) {
		case "a":
		case "A":
		case "e":
		case "E":
		case "i":
		case "I":
		case "o":
		case "O":
		case "u":
		case "U":
			System.out.println("Vowel");
			break;
			default:System.out.println("consonent");
			break;
				
			
		}

	}

}
